class Solution {
public:
    vector<int> fairCandySwap(vector<int>& aliceSizes, vector<int>& bobSizes) {
        long long sumA = 0, sumB = 0;
        for (int x : aliceSizes) sumA += x;
        for (int x : bobSizes) sumB += x;
        int diff = (int)((sumA - sumB) / 2);
        unordered_set<int> aliceSet(aliceSizes.begin(), aliceSizes.end());
        for (int y : bobSizes) {
            if (aliceSet.count(y + diff)) {
                return {y + diff, y};
            }
        }
        return {};
    }
};
